476→/* ------------------------------------------------------------------ */
477→/* Session context validation                                           */
478→/* ------------------------------------------------------------------ */
479→
480→/**
481→ * Structural validation of the caller-assembled session context (wiring
482→ * bugs throw typed errors — mirroring the gateway's validateQuery). Checks
483→ * ids, focus shapes and the default-focus reference.
484→ */
485→export function validateAgentSessionContext(session: AgentSessionContext): void {
486→  if (session.sessionId.trim().length === 0) {
487→    throw new SolutionCompilerError("invalid_session", "sessionId must be a non-empty string");
488→  }
489→  if (session.agentId.trim().length === 0) {
490→    throw new SolutionCompilerError("invalid_session", "agentId must be a non-empty string");
491→  }
492→  const foci = session.foci ?? [];
493→  const focusIds = new Set<string>();
494→  for (const focus of foci) {
495→    if (focus.focusId.trim().length === 0) {
496→      throw new SolutionCompilerError("invalid_session", "every focus must carry a focusId");
497→    }
498→    if (focusIds.has(focus.focusId)) {
499→      throw new SolutionCompilerError(
500→        "invalid_session",
501→        `focus id '${focus.focusId}' is declared more than once`,
502→      );
503→    }
504→    focusIds.add(focus.focusId);
505→    if (focus.nodeRefs.length === 0 && focus.geometryRefs.length === 0) {
506→      throw new SolutionCompilerError(
507→        "invalid_session",
508→        `focus '${focus.focusId}' must anchor to reality (≥1 nodeRef or geometryRef)`,
509→      );
510→    }
511→  }
512→  if (
513→    session.defaultFocusId !== undefined &&
514→    !focusIds.has(session.defaultFocusId)
515→  ) {
516→    throw new SolutionCompilerError(
517→      "invalid_session",
518→      `defaultFocusId '${session.defaultFocusId}' names no declared focus`,
519→    );
520→  }
521→}
