523→/** The advisory Phase 1 building domain used by compiled intents. */
524→export type { SolutionDomainDescriptor } from "@aise/solution-contract";
525→/** The solution/version an intent proposes into (contract type re-export). */
526→export type { IntentProposalContext } from "@aise/solution-contract";
527→

  1→/**
  2→ * PROD-023 — the clarification + proposal INTERACTION LOOP (interaction.ts).
  3→ *
  4→ * `decideNextTurn` maps one user turn to the next agent turn of the
  5→ * interactive engineering solution workflow:
  6→ *
  7→ *   - CLARIFY: a clarification-needed compilation becomes targeted
  8→ *     questions; the pending clarification remembers the original request
  9→ *     so the next user turn ("the depth is 2 m") MERGES into it and
 10→ *     recompiles — ask → answer → complete, never an invented value;
 11→ *   - PROPOSE: a compiled operation intent is shown to the user BEFORE
 12→ *     execution — the typed intent rendered as its canonical command, its
 13→ *     affected target, the quantities computable from parameters alone,
 14→ *     the irreversible flag and the declared review requirements (every
 15→ *     typed operation has material consequences, so every operation is
 16→ *     proposed first);
 17→ *   - DISPATCH: a user confirmation hands the intent to the tool port as
 18→ *     a typed `apply` command (the loop NEVER executes anything itself —
 19→ *     `executeDecision` calls ONLY the port and echoes the response with
 20→ *     its authority label, never re-authored); read-only tool commands
 21→ *     (navigation/explanation/inspection/BOQ-step lookup/validate)
 22→ *     dispatch directly;
 23→ *   - HONEST STATES: ambiguity (readings listed), unsupported and
 24→ *     unsafe-refusal outcomes pass through unchanged — the agent never
 25→ *     guesses and never claims authority.
 26→ *
 27→ * DETERMINISM: pure decision function over the compiler's typed output
 28→ * (no clock of its own, no I/O, no randomness). A new command issued
 29→ * while a clarification or proposal is pending replaces it (the pending
 30→ * state is dropped — the user's latest request governs).
 31→ */
 32→
 33→import type { EngineeringOperationIntent } from "@aise/solution-contract";
 34→import type {
 35→  AgentSessionContext,
 36→  AmbiguousCompiledCommand,
 37→  ClarificationQuestion,
 38→  CommandAttribution,
 39→  CompiledCommand,
 40→  EstimatedQuantity,
 41→  OperationProposal,
 42→  SolutionCommandCompiler,
 43→  UnsafeRefusalCompiledCommand,
 44→  UnsupportedCompiledCommand,
 45→} from "./model";
 46→import type { ApplyToolCommand, SolutionToolCommand, SolutionToolPort, SolutionToolResponse } from "./tools";
 47→import { CANCELLATION_PATTERN, CONFIRMATION_PATTERN } from "./vocabulary";
 48→import {
 49→  estimateOperationQuantities,
 50→  isIrreversibleOperation,
 51→  reviewRequirementsOf,
 52→} from "./quantities";
