145→/* ------------------------------------------------------------------ */
146→/* The loop                                                             */
147→/* ------------------------------------------------------------------ */
148→
149→/**
150→ * Decides the next agent turn for one user utterance. PURE with respect
151→ * to effects: it compiles (through the injected compiler) and decides —
152→ * it NEVER executes anything itself. A pending clarification merges the
153→ * user's answer into the original request and recompiles; a pending
154→ * proposal plus a confirmation becomes a dispatch decision.
155→ */
156→export async function decideNextTurn(
157→  input: TurnInput,
158→  compiler: SolutionCommandCompiler,
159→): Promise<TurnDecision> {
160→  const utterance = input.utterance;
161→  const session = input.session;
162→
163→  /* 1. Confirmation of a pending proposal → dispatch to the tool port. */
164→  const pendingProposal = input.pendingProposal;
165→  if (pendingProposal !== undefined) {
166→    if (CONFIRMATION_PATTERN.test(utterance.trim())) {
167→      return dispatchOf(pendingProposal.proposal);
168→    }
169→    if (CANCELLATION_PATTERN.test(utterance.trim())) {
170→      return { decision: "cancelled", note: "the pending proposal was cancelled by the user" };
171→    }
172→    // Not a confirmation/cancellation: treat as a NEW command (the pending
173→    // proposal is dropped — the user's latest request governs).
174→  }
175→
176→  /* 2. Pending clarification → try the merged recompilation first. */
177→  const pendingClarification = input.pendingClarification;
178→  if (pendingClarification !== undefined) {
179→    if (CANCELLATION_PATTERN.test(utterance.trim())) {
180→      return {
181→        decision: "cancelled",
182→        note: "the pending clarification was cancelled by the user",
183→      };
184→    }
185→    const merged = `${pendingClarification.utterance} ${utterance}`;
186→    const mergedOutcome = await compiler.compile({ utterance: merged, session });
187→    if (mergedOutcome.kind === "operation-intent") {
188→      return proposeOf(mergedOutcome.intent, mergedOutcome.attribution, merged, session);
189→    }
190→    if (
191→      mergedOutcome.kind === "clarification-needed" &&
192→      !sameQuestions(mergedOutcome.questions, pendingClarification.questions)
193→    ) {
194→      // The answer made progress: ask only what remains.
195→      return askOf(merged, mergedOutcome.questions);
196→    }
197→    // The answer did not resolve the request (same questions again, or a
198→    // merged ambiguity/unsupported/unsafe state): fall through and treat
199→    // the utterance as a NEW command — the user's latest request governs.
200→  }
201→
202→  /* 3. Fresh compilation of the utterance. */
203→  const outcome = await compiler.compile({ utterance, session });
204→  return decisionOfOutcome(outcome, utterance, session);
205→}
206→
207→function decisionOfOutcome(
208→  outcome: CompiledCommand,
209→  utterance: string,
210→  session: AgentSessionContext,
211→): TurnDecision {
212→  switch (outcome.kind) {
213→    case "operation-intent":
214→      return proposeOf(outcome.intent, outcome.attribution, utterance, session);
215→    case "clarification-needed":
216→      return askOf(utterance, outcome.questions);
217→    case "tool-command":
218→      return { decision: "dispatch-tool", command: outcome.command };
219→    case "unsupported":
220→      return { decision: "unsupported", command: outcome };
221→    case "ambiguous":
222→      return { decision: "ambiguous", command: outcome };
223→    case "unsafe-refusal":
224→      return { decision: "refuse", command: outcome };
225→  }
226→}
227→
228→function askOf(
229→  utterance: string,
230→  questions: readonly ClarificationQuestion[],
231→): AskTurnDecision {
232→  return {
233→    decision: "ask",
234→    questions,
235→    pendingClarification: { utterance, questions },
236→  };
237→}
238→
239→function proposeOf(
240→  intent: EngineeringOperationIntent,
241→  attribution: CommandAttribution,
242→  utterance: string,
243→  session: AgentSessionContext,
244→): ProposeTurnDecision {
245→  const proposal = buildOperationProposal(intent, attribution, session);
246→  return {
247→    decision: "propose",
248→    proposal,
249→    pendingProposal: { proposal, utterance },
250→  };
251→}
252→
253→/**
254→ * Builds the operation proposal shown to the user BEFORE execution: the
255→ * typed intent rendered as its canonical command, the affected target,
256→ * the quantities computable from parameters alone (plus the focus's
257→ * caller-known area for surface layers), the irreversible flag and the
258→ * declared review requirements.
259→ */
260→export function buildOperationProposal(
261→  intent: EngineeringOperationIntent,
262→  attribution: CommandAttribution,
263→  session: AgentSessionContext,
264→): OperationProposal {
265→  const focus = (session.foci ?? []).find(
266→    (candidate) =>
267→      candidate.nodeRefs.some((nodeRef) => intent.target.nodeRefs.includes(nodeRef)) ||
268→      candidate.geometryRefs.some((geometryRef) =>
269→        intent.target.geometryRefs.some((ref) => ref.ref === geometryRef.ref),
270→      ),
271→  );
272→  const knownArea = focus?.knownParameters?.find(
273→    (parameter) => parameter.name === "area" && parameter.unit === "m2",
274→  );
275→  const estimatedQuantities: readonly EstimatedQuantity[] = estimateOperationQuantities(
276→    intent.operationType,
277→    intent.parameters,
278→    typeof knownArea?.value === "number" ? knownArea.value : undefined,
279→  );
280→  return {
281→    intent,
282→    attribution,
283→    renderedCommand: attribution.normalizedCommandText,
284→    target: {
285→      description: intent.target.description,
286→      selectorKind: intent.target.selectorKind,
287→      nodeRefs: [...intent.target.nodeRefs],
288→      geometryRefs: intent.target.geometryRefs.map((ref) => ({ ...ref })),
289→    },
290→    estimatedQuantities,
291→    irreversible: isIrreversibleOperation(intent.operationType),
292→    reviewRequirements: reviewRequirementsOf(intent.operationType),
293→  };
294→}
295→
296→function dispatchOf(proposal: OperationProposal): DispatchOperationTurnDecision {
297→  const proposedTo = proposal.intent.proposedTo;
298→  const solutionId = proposedTo?.solutionId ?? "";
299→  const versionNumber = proposedTo?.versionNumber ?? 1;
300→  const command: ApplyToolCommand = {
301→    kind: "apply",
302→    attribution: proposal.attribution,
303→    intent: proposal.intent,
304→    solutionId,
305→    versionNumber,
306→  };
307→  return { decision: "dispatch-operation", command, proposal };
308→}
309→
310→function sameQuestions(
311→  left: readonly ClarificationQuestion[],
312→  right: readonly ClarificationQuestion[],
313→): boolean {
314→  if (left.length !== right.length) {
315→    return false;
316→  }
317→  return left.every(
318→    (question, index) =>
319→      right[index] !== undefined &&
320→      question.slotKind === right[index]?.slotKind &&
321→      question.slot === right[index]?.slot &&
322→      question.question === right[index]?.question,
323→  );
324→}
