326→/* ------------------------------------------------------------------ */
327→/* Execution (the ONLY effect surface: the tool port)                   */
328→/* ------------------------------------------------------------------ */
329→
330→/** Typed error for executing a non-dispatchable decision. */
331→export class TurnExecutionError extends Error {
332→  constructor(decision: string) {
333→    super(`turn decision '${decision}' is not dispatchable through the tool port`);
334→    this.name = "TurnExecutionError";
335→  }
336→}
337→
338→/**
339→ * Executes a dispatch decision through the tool port — the loop's ONLY
340→ * effect surface. The port's response is returned VERBATIM (its authority
341→ * label included, never re-authored); nothing else is touched.
342→ */
343→export async function executeDecision(
344→  port: SolutionToolPort,
345→  decision: TurnDecision,
346→): Promise<SolutionToolResponse> {
347→  if (decision.decision === "dispatch-operation" || decision.decision === "dispatch-tool") {
348→    return port.call(decision.command);
349→  }
350→  throw new TurnExecutionError(decision.decision);
351→}
