232→
233→/* ------------------------------------------------------------------ */
234→/* The canonical tool-command builder (used by the compiler)            */
235→/* ------------------------------------------------------------------ */
236→
237→type AttributionBase = Omit<CommandAttribution, "normalizedCommand" | "normalizedCommandText">;
238→
239→/**
240→ * Builds the typed tool command of one agent tool request with its
241→ * canonical normalized command text. The returned command's attribution
242→ * carries the normalized text; the canonical SERIALIZATION is filled by
243→ * the caller (compiler.ts `serializeToolCommand`) to avoid recursion.
244→ */
245→export function toolCommandOf(
246→  toolKind: AgentToolCommandKind,
247→  utterance: string,
248→  solutionRef: IntentProposalContext,
249→  attributionBase: AttributionBase,
250→): { readonly command: SolutionToolCommand; readonly normalizedCommandText: string } {
251→  const { solutionId, versionNumber } = solutionRef;
252→  const stepIndex = extractStepIndex(utterance);
253→  const navigationTarget = navigationTargetOf(utterance);
254→  const attribution: CommandAttribution = {
255→    ...attributionBase,
256→    normalizedCommand: "",
257→    normalizedCommandText: "",
258→  };
259→  switch (toolKind) {
260→    case "validate":
261→      return {
262→        command: { kind: "validate", attribution, solutionId, versionNumber },
263→        normalizedCommandText: "Validate the solution.",
264→      };
265→    case "inspect":
266→      return {
267→        command: { kind: "inspect", attribution, solutionId, versionNumber },
268→        normalizedCommandText: "Inspect the current proposed state.",
269→      };
270→    case "navigate": {
271→      const command: NavigateToolCommand = {
272→        kind: "navigate",
273→        attribution,
274→        solutionId,
275→        versionNumber,
276→        target:
277→          navigationTarget === "goto-step"
278→            ? { kind: "goto-step", stateIndex: stepIndex ?? 0 }
279→            : { kind: navigationTarget },
280→      };
281→      const index = command.target.stateIndex ?? 0;
282→      const normalizedCommandText =
283→        navigationTarget === "list-steps"
284→          ? "List the solution steps."
285→          : navigationTarget === "current-state"
286→            ? "Show the current proposed state."
287→            : index === 0
288→              ? "Show the baseline state."
289→              : `Show step ${index}.`;
290→      return { command, normalizedCommandText };
291→    }
292→    case "explain": {
293→      const index = stepIndex ?? 1;
294→      return {
295→        command: { kind: "explain", attribution, solutionId, versionNumber, operationIndex: index },
296→        normalizedCommandText: `Explain step ${index}.`,
297→      };
298→    }
299→    case "boq-step-lookup": {
300→      const index = stepIndex ?? 1;
301→      return {
302→        command: {
303→          kind: "boq-step-lookup",
304→          attribution,
305→          solutionId,
306→          versionNumber,
307→          operationIndex: index,
308→        },
309→        normalizedCommandText: `Look up the BOQ lines for step ${index}.`,
310→      };
311→    }
312→    default: {
313→      const exhaustive: never = toolKind;
314→      throw new Error(`unknown tool kind: ${String(exhaustive)}`);
315→    }
316→  }
317→}
318→
319→/** Renders the canonical normalized text of a built tool command. */
320→export function toolCommandText(command: SolutionToolCommand): string {
321→  switch (command.kind) {
322→    case "validate":
323→      return "Validate the solution.";
324→    case "inspect":
325→      return "Inspect the current proposed state.";
326→    case "navigate": {
327→      if (command.target.kind === "list-steps") {
328→        return "List the solution steps.";
329→      }
330→      if (command.target.kind === "current-state") {
331→        return "Show the current proposed state.";
332→      }
333→      return (command.target.stateIndex ?? 0) === 0
334→        ? "Show the baseline state."
335→        : `Show step ${command.target.stateIndex}.`;
336→    }
337→    case "apply":
338→      return `Apply the proposed ${command.intent.operationType} operation.`;
339→    case "explain":
340→      return `Explain step ${command.operationIndex}.`;
341→    case "boq-step-lookup":
342→      return `Look up the BOQ lines for step ${command.operationIndex}.`;
343→    default: {
344→      const exhaustive: never = command;
345→      throw new Error(`unknown tool command: ${String(exhaustive)}`);
346→    }
347→  }
348→}
349→
350→/** Every agent tool command kind (runtime vocabulary check). */
351→export function isAgentToolCommandKind(value: unknown): value is AgentToolCommandKind {
352→  return (
353→    typeof value === "string" && (AGENT_TOOL_COMMAND_KINDS as readonly string[]).includes(value)
354→  );
355→}
