357→/* ------------------------------------------------------------------ */
358→/* The IN-MEMORY TEST DOUBLE (clearly labeled — NOT the engine)         */
359→/* ------------------------------------------------------------------ */
360→
361→/** Construction options of the test double. */
362→export interface InMemorySolutionToolDoubleOptions {
363→  /** Injected clock (the double owns no wall time). */
364→  readonly clock: () => string;
365→  readonly solutionId: string;
366→  readonly versionNumber: number;
367→  readonly baselineRealityVersionId: string;
368→}
369→
370→/**
371→ * The recording surface of the double — the TOOL TRACE every guarantee is
372→ * tested against: every call, in order, with its full attribution.
373→ */
374→export interface InMemorySolutionToolDouble extends SolutionToolPort {
375→  /** Every command the double received, in call order. */
376→  readonly calls: readonly SolutionToolCommand[];
377→  /** The intents applied through the double, in apply order. */
378→  readonly appliedIntents: readonly EngineeringOperationIntent[];
379→}
380→
381→/**
382→ * A clearly-labeled IN-MEMORY TEST DOUBLE of the solution tool port —
383→ * deterministic, offline, honest about being a double (its validate
384→ * response reports `unknown` for every engine-owned check; its BOQ rows
385→ * are placeholder traces). It records every call so tests prove the
386→ * attribution + normalized-command guarantees and that the ONLY effect
387→ * surface of the agent path is this port.
388→ */
389→export function createInMemorySolutionToolDouble(
390→  options: InMemorySolutionToolDoubleOptions,
391→): InMemorySolutionToolDouble {
392→  const calls: SolutionToolCommand[] = [];
393→  const appliedIntents: EngineeringOperationIntent[] = [];
394→  const applied: {
395→    operationIndex: number;
396→    operationId: string;
397→    operationType: string;
398→    parameters: readonly TypedOperationParameter[];
399→    effects: readonly OperationEffect[];
400→  }[] = [];
401→
402→  const double: InMemorySolutionToolDouble = {
403→    descriptor: {
404→      toolId: "solution-tool-double-in-memory",
405→      engineKind: "in-memory-test-double",
406→      engineVersion: "1.0.0",
407→    },
408→    calls,
409→    appliedIntents,
410→    call: async (command: SolutionToolCommand): Promise<SolutionToolResponse> => {
411→      calls.push(command);
412→      switch (command.kind) {
413→        case "validate": {
414→          const inputDigest = sha256Hex(
415→            canonicalJsonStringify(applied.map((entry) => entry.operationId)),
416→          );
417→          const checks = [
418→            {
419→              checkId: "units.parameters-typed",
420→              result: "pass" as const,
421→              detail:
422→                `every numeric parameter of all ${applied.length} applied ` +
423→                `operations carries an explicit unit (checked by the test double)`,
424→            },
425→            {
426→              checkId: "geometry.rules",
427→              result: "unknown" as const,
428→              detail:
429→                "geometry/topology rule checks belong to the production " +
430→                "solution engine (this is a TEST DOUBLE — it never claims " +
431→                "validation authority)",
432→            },
433→          ];
434→          const outcome = validationOutcomeWorstOf(checks.map((check) => check.result));
435→          const snapshot: SolutionValidationSnapshot = {
436→            contractVersion: SOLUTION_CONTRACT_VERSION,
437→            snapshotId: deriveValidationSnapshotId({
438→              solutionId: command.solutionId,
439→              versionNumber: command.versionNumber,
440→              inputDigest,
441→              engineKind: double.descriptor.engineKind,
442→              engineVersion: double.descriptor.engineVersion,
443→              outcome,
444→            }),
445→            solutionId: command.solutionId,
446→            versionNumber: command.versionNumber,
447→            outcome,
448→            checks,
449→            inputDigest,
450→            engine: {
451→              kind: double.descriptor.engineKind,
452→              version: double.descriptor.engineVersion,
453→            },
454→            validatedAt: options.clock(),
455→          };
456→          return { kind: "validation-report", authority: "solution-engine", snapshot };
457→        }
458→        case "apply": {
459→          const intent = command.intent;
460→          const operationIndex = applied.length + 1;
461→          const operationId = deriveEngineeringOperationId(
462→            operationSemanticIdentityOfIntent(intent, {
463→              solutionId: command.solutionId,
464→              versionNumber: command.versionNumber,
465→              operationIndex,
466→            }),
467→          );
468→          const estimates = estimateOperationQuantities(
469→            intent.operationType,
470→            intent.parameters,
471→          );
472→          const effects: OperationEffect[] = estimates.map((estimate) => ({
473→            contractVersion: SOLUTION_CONTRACT_VERSION,
474→            effectKind: "quantity-impact" as const,
475→            quantity: {
476→              dimension: estimate.dimension,
477→              value: estimate.value,
478→              unit: estimate.unit,
479→              calculationRef: "in-memory-test-double:parameter-arithmetic",
480→            },
481→            direction: intent.operationType === "demolition-removal" ? "removed" : "added",
482→            affectedNodeRefs: [...intent.target.nodeRefs],
483→            geometryRefs: intent.target.geometryRefs.map((ref) => ({ ...ref })),
484→          }));
485→          const resultingStateId = deriveProposedStateId({
486→            solutionId: command.solutionId,
487→            versionNumber: command.versionNumber,
488→            stateIndex: operationIndex,
489→            baselineRealityVersionId: options.baselineRealityVersionId,
490→            appliedOperationIds: applied.map((entry) => entry.operationId),
491→          });
492→          applied.push({
493→            operationIndex,
494→            operationId,
495→            operationType: intent.operationType,
496→            parameters: intent.parameters,
497→            effects,
498→          });
499→          appliedIntents.push(intent);
500→          return {
501→            kind: "apply-accepted",
502→            authority: "solution-engine",
503→            operationId,
504→            resultingStateId,
505→            effects,
506→          };
507→        }
508→        case "inspect":
509→          return {
510→            kind: "inspection-report",
511→            authority: "solution-engine",
512→            operationCount: applied.length,
513→            operations: applied.map((entry) => ({
514→              operationIndex: entry.operationIndex,
515→              operationId: entry.operationId,
516→              operationType: entry.operationType,
517→              parameters: entry.parameters,
518→            })),
519→          };
520→        case "navigate": {
521→          const stateIndex =
522→            command.target.kind === "goto-step"
523→              ? (command.target.stateIndex ?? 0)
524→              : command.target.kind === "current-state"
525→                ? applied.length
526→                : 0;
527→          return {
528→            kind: "navigation-report",
529→            authority: "solution-graph",
530→            target: command.target.kind,
531→            stateIndex,
532→            appliedOperationIds: applied.slice(0, stateIndex).map((entry) => entry.operationId),
533→          };
534→        }
535→        case "explain": {
536→          const entry = applied.find((item) => item.operationIndex === command.operationIndex);
537→          if (entry === undefined) {
538→            return {
539→              kind: "tool-refusal",
540→              authority: "solution-tool",
541→              reason:
542→                `the test double has no operation at index ${command.operationIndex} ` +
543→                `(applied operations: ${applied.length})`,
544→            };
545→          }
546→          return {
547→            kind: "explanation-report",
548→            authority: "solution-engine",
549→            operationIndex: entry.operationIndex,
550→            operationId: entry.operationId,
551→            operationType: entry.operationType,
552→            parameters: entry.parameters,
553→            effects: entry.effects,
554→          };
555→        }
556→        case "boq-step-lookup": {
557→          const entry = applied.find((item) => item.operationIndex === command.operationIndex);
558→          if (entry === undefined) {
559→            return {
560→              kind: "tool-refusal",
561→              authority: "solution-tool",
562→              reason:
563→                `the test double has no operation at index ${command.operationIndex} ` +
564→                `to trace BOQ lines for (applied operations: ${applied.length})`,
565→            };
566→          }
567→          const lines = entry.effects
568→            .filter((effect) => effect.quantity !== undefined)
569→            .map((effect) => {
570→              const direction = effect.direction ?? "created";
571→              const contributionKind: "created" | "modified" | "removed" =
572→                direction === "removed"
573→                  ? "removed"
574→                  : direction === "changed"
575→                    ? "modified"
576→                    : "created";
577→              return {
578→                boqLineId: `boq-line-${entry.operationIndex}-${effect.quantity?.unit ?? "count"}`,
579→                quantity: effect.quantity?.value ?? 0,
580→                unit: effect.quantity?.unit ?? "count",
581→                contributionKind,
582→              };
583→            });
584→          return {
585→            kind: "boq-trace-report",
586→            authority: "solution-boq-service",
587→            operationIndex: entry.operationIndex,
588→            lines,
589→          };
590→        }
591→        default: {
592→          const exhaustive: never = command;
593→          throw new Error(`unknown tool command: ${String(exhaustive)}`);
594→        }
595→      }
596→    },
597→  };
598→  return double;
599→}
