 1→/**
 2→ * AISE-027 — deterministic pane SVG renderer (shared by the 3D and 2D panes).
 3→ *
 4→ * One `<polygon>` per projected shape (closed contour — the projection
 5→ * engine emits closed boundary polygons), each carrying the shape's
 6→ * `data-node-id` — the stable cross-pane identity anchor shared by the 3D,
 7→ * 2D and BOQ panes — plus the 026 `data-origin` traceability hook. Fixed
 8→ * element order (the projection's node-id-sorted shapes), fixed attribute
 9→ * order, `fmt` canonical numbers → byte-identical SVG for identical input.
10→ *
11→ * PRESENTATION-ONLY DIFFERENTIATION: scenario-authored shapes (origin
12→ * "scenario") render with a DASHED stroke — a presentation distinction the
13→ * viewer draws over 026's verbatim origin vocabulary; it changes no data.
14→ * `selectedNodeId` toggles `data-selected="true"` plus the highlight
15→ * stroke on exactly that node's shape — again presentation only. Honest
16→ * omissions are listed after the drawing as `<li>` entries with their
17→ * stable reason codes. This module is pure string rendering: no DOM, no
18→ * events, no fetching.
19→ */
20→
21→import { boundsOfPoints, escapeHtml, fmt, paddedViewBox, pointsAttr } from "./format";
22→import type { PaneProjection, Point2D } from "./model";
23→
24→/** Pane stroke width (screen units). */
25→export const PANE_STROKE_WIDTH = 1.5;
26→
27→/** Stroke of an unselected projected shape. */
28→export const PANE_STROKE = "#000000";
29→
30→/** Stroke of the SELECTED shape (highlight, presentation only). */
31→export const PANE_SELECTED_STROKE = "#c2410c";
32→
33→/** Dash pattern for scenario-authored (new) elements — presentation only. */
34→export const PANE_SCENARIO_DASH = "4 2";
35→
36→/**
37→ * Deterministic SVG document of a pane projection. `selectedNodeId`
38→ * highlights that node's shape (data-selected + stroke) — presentation
39→ * only; geometry, ids and order are untouched.
40→ */
41→export function renderPaneSvg(projection: PaneProjection, selectedNodeId?: string): string {
42→  const allPoints: Point2D[] = [];
43→  for (const shape of projection.shapes) {
44→    allPoints.push(...shape.points);
45→  }
46→  const box = paddedViewBox(boundsOfPoints(allPoints));
47→  const lines: string[] = [
48→    `<svg height="${box.height}" viewBox="${box.viewBox}" width="${box.width}" xmlns="http://www.w3.org/2000/svg">`,
49→  ];
50→  for (const shape of projection.shapes) {
51→    const selected = selectedNodeId !== undefined && selectedNodeId === shape.nodeId;
52→    const stroke = selected ? PANE_SELECTED_STROKE : PANE_STROKE;
53→    const scenarioAuthored = shape.origin === "scenario";
54→    const dashAttr = scenarioAuthored ? ` stroke-dasharray="${PANE_SCENARIO_DASH}"` : "";
55→    lines.push(
56→      `<polygon data-node-id="${escapeHtml(shape.nodeId)}" data-origin="${escapeHtml(shape.origin)}"${selected ? ` data-selected="true"` : ""} fill="none" points="${pointsAttr(shape.points)}" stroke="${stroke}" stroke-width="${fmt(PANE_STROKE_WIDTH)}"${dashAttr}/>`,
57→    );
58→  }
59→  lines.push("</svg>");
60→  return `${lines.join("\n")}\n`;
61→}
62→
63→/** Honest omission list items: stable node id + reason code, verbatim order. */
64→export function omissionLines(projection: PaneProjection): string[] {
65→  if (projection.omissions.length === 0) {
66→    return [];
67→  }
68→  const lines = [`<ul class="omissions">`];
69→  for (const omission of projection.omissions) {
70→    lines.push(
71→      `<li data-omitted-node-id="${escapeHtml(omission.nodeId)}" data-reason="${escapeHtml(omission.reason)}">${escapeHtml(omission.nodeId)} — ${escapeHtml(omission.reason)}</li>`,
72→    );
73→  }
74→  lines.push(`</ul>`);
75→  return lines;
76→}
77→
78→/** Honest placeholder when a pane has no projectable shapes at all. */
79→export function emptyPaneLines(what: string): string[] {
80→  return [`<p class="pane-empty">No ${what} in this state layer.</p>`];
81→}
82→

  1→/**
  2→ * AISE-021 — deterministic 2D pane renderer (local SVG presentation).
  3→ *
  4→ * The 2D pane renders the floor-plan `Drawing2D` the server assembled from
  5→ * AISE-020's authoritative generator. apps/web cannot import the backend's
  6→ * `toSvg` (boundary matrix: apps → apps/packages only), so this module
  7→ * MIRRORS its semantics over the same structural `Drawing2D` value:
  8→ *
  9→ *  - one shape per drawn element (`<polygon>` / `<polyline>` / opening
 10→ *    symbol `<circle>` + letter `<text>`), each carrying the element's
 11→ *    `data-node-id` — the R5 cross-view selection anchor;
 12→ *  - dimension lines with `data-dimension-id` and the measured value text:
 13→ *    `«value» m ±«σ» m` ONLY when the σ is known; an unknown σ renders with
 14→ *    NO ± at all — never a fabricated ±0 (the "σ unknown" wording lives in
 15→ *    the workspace measurement strip; the SVG keeps 020's convention);
 16→ *  - fixed element order (the drawing's already-sorted arrays), fixed
 17→ *    alphabetical attribute order, `fmt` canonical numbers → byte-identical
 18→ *    SVG for identical drawings.
 19→ *
 20→ * SELECTION: `selectedNodeId` only toggles `data-selected="true"` plus the
 21→ * highlight stroke on exactly that node's elements — never the geometry,
 22→ * ids or order. This module is pure string rendering: no DOM, no events,
 23→ * no fetching (the workspace is server-rendered; interactivity is a thin
 24→ * navigation shell outside this package's authority).
 25→ */
 26→
 27→import { boundsOfPoints, escapeHtml, fmt, paddedViewBox, pointsAttr } from "./format";
 28→import type { Dimension2D, DrawnElement, Drawing2D, Point2D } from "./model";
 29→
 30→/** Opening symbol radius in metres (× drawing scale). */
 31→const SVG_SYMBOL_RADIUS_M = 0.2;
 32→
 33→/** Minimum symbol radius in drawing units (visible at scale 1). */
 34→const SVG_SYMBOL_MIN_RADIUS = 0.5;
 35→
 36→/** Text height as a fraction of the drawing extent (min 1 drawing unit). */
 37→const SVG_TEXT_HEIGHT_FRACTION = 0.05;
 38→
 39→/** Stroke of an unselected 2D element. */
 40→export const DRAWING_STROKE = "#000000";
 41→
 42→/** Stroke of the SELECTED 2D element (highlight, presentation only). */
 43→export const DRAWING_SELECTED_STROKE = "#c2410c";
 44→
 45→/** Dimension line stroke (mirrors AISE-020's svg.ts). */
 46→const DIMENSION_STROKE = "#333333";
 47→
 48→/**
 49→ * Deterministic SVG document of a drawing. `selectedNodeId` highlights that
 50→ * node's elements (data-selected + stroke) — presentation only.
 51→ */
 52→export function renderDrawing2dSvg(drawing: Drawing2D, selectedNodeId?: string): string {
 53→  const points: Point2D[] = [];
 54→  for (const element of drawing.elements) {
 55→    collectElementPoints(element, points);
 56→  }
 57→  for (const dimension of drawing.dimensions) {
 58→    points.push(dimension.from, dimension.to);
 59→  }
 60→
 61→  const bounds = boundsOfPoints(points);
 62→  const width = bounds.maxX - bounds.minX;
 63→  const height = bounds.maxY - bounds.minY;
 64→  const extent = Math.max(width, height);
 65→  const fontSize = extent > 0 ? Math.max(extent * SVG_TEXT_HEIGHT_FRACTION, 1) : 1;
 66→  const box = paddedViewBox(bounds);
 67→
 68→  const lines: string[] = [
 69→    `<svg height="${box.height}" viewBox="${box.viewBox}" width="${box.width}" xmlns="http://www.w3.org/2000/svg">`,
 70→  ];
 71→  for (const element of drawing.elements) {
 72→    lines.push(...elementSvg(element, drawing.coordinateFrame.scale, fontSize, selectedNodeId));
 73→  }
 74→  for (const dimension of drawing.dimensions) {
 75→    lines.push(...dimensionSvg(dimension, fontSize));
 76→  }
 77→  lines.push("</svg>");
 78→  return `${lines.join("\n")}\n`;
 79→}
 80→
 81→/* ------------------------------------------------------------------ */
 82→/* Elements                                                            */
 83→/* ------------------------------------------------------------------ */
 84→
 85→function collectElementPoints(element: DrawnElement, into: Point2D[]): void {
 86→  if (element.geometry2d.kind === "point") {
 87→    into.push(element.geometry2d.point);
 88→  } else {
 89→    into.push(...element.geometry2d.points);
 90→  }
 91→  if (element.label !== undefined) {
 92→    into.push(element.label.anchor);
 93→  }
 94→}
 95→
 96→function elementSvg(
 97→  element: DrawnElement,
 98→  scale: number,
 99→  fontSize: number,
100→  selectedNodeId: string | undefined,
101→): string[] {
102→  const selected = selectedNodeId !== undefined && selectedNodeId === element.sourceNodeId;
103→  const stroke = selected ? DRAWING_SELECTED_STROKE : DRAWING_STROKE;
104→  const selectedAttr = selected ? ` data-selected="true"` : "";
105→  const weight = fmt(element.style.strokeWeight);
106→  const geometry = element.geometry2d;
107→  const lines: string[] = [];
108→  if (geometry.kind === "polygon") {
109→    lines.push(
110→      `<polygon data-node-id="${escapeHtml(element.elementId)}"${selectedAttr} fill="none" points="${pointsAttr(geometry.points)}" stroke="${stroke}" stroke-width="${weight}"/>`,
111→    );
112→  } else if (geometry.kind === "polyline") {
113→    lines.push(
114→      `<polyline data-node-id="${escapeHtml(element.elementId)}"${selectedAttr} fill="none" points="${pointsAttr(geometry.points)}" stroke="${stroke}" stroke-width="${weight}"/>`,
115→    );
116→  } else {
117→    const radius = fmt(Math.max(SVG_SYMBOL_MIN_RADIUS, SVG_SYMBOL_RADIUS_M * scale));
118→    lines.push(
119→      `<circle cx="${fmt(geometry.point[0])}" cy="${fmt(geometry.point[1])}" data-node-id="${escapeHtml(element.elementId)}"${selectedAttr} fill="none" r="${radius}" stroke="${stroke}" stroke-width="${weight}"/>`,
120→    );
121→    lines.push(
122→      `<text font-size="${fmt(fontSize)}" x="${fmt(geometry.point[0])}" y="${fmt(geometry.point[1])}">${escapeHtml(symbolLetter(geometry.symbol))}</text>`,
123→    );
124→  }
125→  if (element.label !== undefined) {
126→    lines.push(
127→      `<text font-size="${fmt(fontSize)}" x="${fmt(element.label.anchor[0])}" y="${fmt(element.label.anchor[1])}">${escapeHtml(element.label.text)}</text>`,
128→    );
129→  }
130→  return lines;
131→}
132→
133→function symbolLetter(symbol: "door" | "window" | "opening"): string {
134→  return symbol === "door" ? "D" : symbol === "window" ? "W" : "O";
135→}
136→
137→/* ------------------------------------------------------------------ */
138→/* Dimensions                                                          */
139→/* ------------------------------------------------------------------ */
140→
141→function dimensionSvg(dimension: Dimension2D, fontSize: number): string[] {
142→  const midX = (dimension.from[0] + dimension.to[0]) / 2;
143→  const midY = (dimension.from[1] + dimension.to[1]) / 2;
144→  // σ discipline: unknown σ renders with NO ± — never a fabricated ±0.
145→  const text =
146→    dimension.uncertainty === null
147→      ? `${fmt(dimension.value)} m`
148→      : `${fmt(dimension.value)} m ±${fmt(dimension.uncertainty)} m`;
149→  return [
150→    `<line data-dimension-id="${escapeHtml(dimension.dimensionId)}" stroke="${DIMENSION_STROKE}" stroke-width="1" x1="${fmt(dimension.from[0])}" x2="${fmt(dimension.to[0])}" y1="${fmt(dimension.from[1])}" y2="${fmt(dimension.to[1])}"/>`,
151→    `<text font-size="${fmt(fontSize)}" x="${fmt(midX)}" y="${fmt(midY - fontSize)}">${escapeHtml(text)}</text>`,
152→  ];
153→}
