 53→
 54→export type Geometry2D = Polyline2D | Polygon2D | PointSymbol2D;
 55→
 56→/** Presentation vocabulary carried explicitly on every drawn element. */
 57→export type StrokeKind = "wall" | "boundary" | "opening" | "dimension" | "annotation";
 58→
 59→export interface Style2D {
 60→  readonly strokeKind: StrokeKind;
 61→  readonly strokeWeight: number;
 62→}
 63→
 64→export interface Label2D {
 65→  readonly text: string;
 66→  readonly anchor: Point2D;
 67→}
