 69→/**
 70→ * Uncertainty of a drawn element: physical 1σ of its source geometry
 71→ * (null = unknown — NEVER 0) plus the ids the σ propagated from.
 72→ */
 73→export interface Uncertainty2D {
 74→  readonly sigma: number | null;
 75→  readonly propagatedFrom: readonly string[];
