318→
319→/**
320→ * EVERYTHING the workspace renders. Assembled entirely server-side; the
321→ * browser never fetches, never derives and never mutates it.
322→ */
323→export interface WorkspaceInput {
324→  /** Floor-plan drawing pinned to `sourceVersionId` (AISE-020 output). */
325→  readonly drawing: Drawing2D;
326→  /** Graph snapshot slice for the SAME version (wireframe + properties). */
327→  readonly graphSnapshot: GraphSnapshot;
328→  /** Evidence records linked by stable node ids (never fetched here). */
329→  readonly evidence: readonly EvidenceEntry[];
330→  /** The currently selected stable node id (presentation only). */
331→  readonly selectedNodeId?: string;
332→  /** Server-computed review state, rendered verbatim (never altered). */
333→  readonly review?: ReviewState;
334→  /** Axonometric view parameters for the 3D pane (default when absent). */
335→  readonly view?: ViewParams;
336→}
