  1→/**
  2→ * AISE-021 — `renderWorkspace`: the browser engineering workspace document.
  3→ *
  4→ * ⚠⚠⚠ NO BROWSER-SIDE AUTHORITY (frozen invariant, architecture-lock
  5→ * "Authority" #8: UI state is never canonical) ⚠⚠⚠
  6→ *
  7→ * `renderWorkspace(input)` is a PURE FUNCTION from a server-assembled
  8→ * `WorkspaceInput` to ONE complete HTML document string:
  9→ *
 10→ *  - the 2D pane (floor-plan SVG, every element carrying `data-node-id`);
 11→ *  - the 3D pane (deterministic axonometric wireframe, same `data-node-id`s
 12→ *    — see wireframe.ts: an engineering wireframe, NOT a 3D engine);
 13→ *  - the evidence pane (server-provided records, linked BY NODE ID — one
 14→ *    row per entry×node link so every row carries exactly one
 15→ *    `data-node-id`; invalidated records carry an explicit INVALID marker);
 16→ *  - the measurement strip (every dimension: value + unit + σ, where an
 17→ *    unknown σ reads "σ unknown" — never a fabricated ±0);
 18→ *  - the review banner — the SERVER's review state rendered VERBATIM. The
 19→ *    workspace NEVER computes, infers, defaults or alters a review status;
 20→ *    there is no code path that could, by design;
 21→ *  - the selection panel for `selectedNodeId` — `resolveSelection` output,
 22→ *    i.e. the R5 cross-view resolution of ONE stable id.
 23→ *
 24→ * SELECTION CHANGES PRESENTATION ONLY: `data-selected="true"` attributes and
 25→ * the highlight stroke on exactly that node's elements in both panes plus
 26→ * the selection panel. Geometry, ids, ordering and every input value are
 27→ * untouched; two renders of the same input are BYTE-IDENTICAL (no clock, no
 28→ * randomness, canonical number text, fixed attribute order).
 29→ *
 30→ * The workspace NEVER fetches: all data arrives via `WorkspaceInput`. It
 31→ * also renders honestly what the server DID NOT provide: omitted nodes with
 32→ * their stable reason codes (both panes) and a version-mismatch warning
 33→ * when the drawing's `sourceVersionId` disagrees with the graph snapshot's
 34→ * `versionId` (surfaced, not silently synchronized).
 35→ */
 36→
 37→import { WorkspaceError } from "./errors";
 38→import { escapeHtml, fmt } from "./format";
 39→import type {
 40→  Dimension2D,
 41→  OmittedNode,
 42→  ReviewState,
 43→  SelectionBundle,
 44→  SelectionSigma,
 45→  WorkspaceInput,
 46→  WorkspaceProperty,
 47→} from "./model";
 48→import { renderDrawing2dSvg } from "./svg2d";
 49→import { resolveSelection, viewOf } from "./selection";
 50→import { DEFAULT_VIEW, project3dWireframe, renderWireframeSvg, type WireframeOmission } from "./wireframe";
 51→
 52→/** Version stamped on every workspace document (determinism pin). */
 53→export const WORKSPACE_GENERATOR_VERSION = "aise-workspace/1.0";
 54→
 55→/** Fixed stylesheet — a constant string, never derived from input data. */
 56→const WORKSPACE_CSS = `main.panes,header,footer,.selection-panel{max-width:64rem;margin:0 auto;padding:0 1rem}
 57→.panes{display:grid;grid-template-columns:1fr 1fr;gap:1rem}
 58→.pane,.selection-panel,header,footer{font:14px/1.45 system-ui,sans-serif;color:#1c1917}
 59→.pane{border:1px solid #d6d3d1;border-radius:6px;padding:.75rem;background:#fff}
 60→.pane svg,.selection-panel svg{width:100%;height:auto;display:block}
 61→.pane-note,.version-pin,.workspace-footer{color:#57534e;font-size:12px}
 62→.version-warning{color:#9a3412;font-weight:600}
 63→.review-banner{border:1px solid #d97706;background:#fffbeb;border-radius:6px;padding:.5rem .75rem;margin:.5rem 1rem}
 64→.review-banner[data-review-status=rejected]{border-color:#b91c1c;background:#fef2f2}
 65→.review-banner[data-review-status=approved]{border-color:#15803d;background:#f0fdf4}
 66→.evidence-list,.measurement-strip,.omissions,.selection-properties,.selection-sigmas,.selection-2d,.selection-3d,.selection-evidence{list-style:none;padding-left:0;margin:.25rem 0}
 67→.evidence-list li,.measurement-strip li,.omissions li{padding:.15rem 0;border-bottom:1px dotted #e7e5e4}
 68→.evidence-list li[data-invalid=true]{color:#b91c1c;text-decoration:line-through}
 69→.sigma-unknown{color:#9a3412}
 70→code{background:#f5f5f4;padding:0 .25rem;border-radius:3px}`;
 71→
 72→/* ------------------------------------------------------------------ */
 73→/* Input validation                                                    */
 74→/* ------------------------------------------------------------------ */
 75→
 76→function requireInput(input: WorkspaceInput): void {
 77→  const drawing = input.drawing;
 78→  if (drawing === null || typeof drawing !== "object" || typeof drawing.sourceVersionId !== "string" || drawing.sourceVersionId.length === 0) {
 79→    throw new WorkspaceError("invalid_input", "drawing requires a non-empty sourceVersionId");
 80→  }
 81→  if (!Array.isArray(drawing.elements) || !Array.isArray(drawing.dimensions) || !Array.isArray(drawing.omittedNodes)) {
 82→    throw new WorkspaceError("invalid_input", "drawing elements/dimensions/omittedNodes must be arrays");
 83→  }
 84→  const snapshot = input.graphSnapshot;
 85→  if (snapshot === null || typeof snapshot !== "object" || typeof snapshot.versionId !== "string" || snapshot.versionId.length === 0) {
 86→    throw new WorkspaceError("invalid_input", "graphSnapshot requires a non-empty versionId");
 87→  }
 88→  if (!Array.isArray(snapshot.nodes)) {
 89→    throw new WorkspaceError("invalid_input", "graphSnapshot.nodes must be an array");
 90→  }
 91→  if (!Array.isArray(input.evidence)) {
 92→    throw new WorkspaceError("invalid_input", "evidence must be an array");
 93→  }
 94→}
 95→
 96→/* ------------------------------------------------------------------ */
 97→/* Document assembly                                                   */
 98→/* ------------------------------------------------------------------ */
 99→
100→/** Render the complete workspace HTML document (deterministic, pure). */
101→export function renderWorkspace(input: WorkspaceInput): string {
102→  requireInput(input);
103→
104→  const view = viewOf(input);
105→  const wireframe = project3dWireframe(input.graphSnapshot, view);
106→  const svg2d = renderDrawing2dSvg(input.drawing, input.selectedNodeId);
107→  const svg3d = renderWireframeSvg(wireframe, input.selectedNodeId);
108→  const selection =
109→    input.selectedNodeId === undefined ? undefined : resolveSelection(input.selectedNodeId, input);
110→
111→  const lines: string[] = [
112→    `<!doctype html>`,
113→    `<html lang="en">`,
114→    `<head>`,
115→    `<meta charset="utf-8"/>`,
116→    `<meta name="viewport" content="width=device-width, initial-scale=1"/>`,
117→    `<title>AISE engineering workspace — ${escapeHtml(input.graphSnapshot.versionId)}</title>`,
118→    `<style>${WORKSPACE_CSS}</style>`,
119→    `</head>`,
120→    `<body class="aise-workspace" data-graph-version="${escapeHtml(input.graphSnapshot.versionId)}" data-drawing-id="${escapeHtml(input.drawing.drawingId)}" data-drawing-generator="${escapeHtml(input.drawing.generatedBy)}" data-workspace-version="${WORKSPACE_GENERATOR_VERSION}">`,
121→    ...headerLines(input),
122→    ...reviewBannerLines(input.review),
123→    `<main class="panes">`,
124→    ...pane2dLines(input, svg2d),
125→    ...pane3dLines(view, svg3d, wireframe.omissions),
126→    ...paneEvidenceLines(input),
127→    ...paneMeasurementLines(input.drawing.dimensions),
128→    `</main>`,
129→    ...(selection === undefined ? [] : selectionPanelLines(selection)),
130→    ...footerLines(),
131→    `</body>`,
132→    `</html>`,
133→  ];
134→  return `${lines.join("\n")}\n`;
135→}
136→
137→function headerLines(input: WorkspaceInput): string[] {
138→  const lines = [
139→    `<header class="workspace-header">`,
140→    `<h1>AISE engineering workspace</h1>`,
141→    `<p class="version-pin">2D floor plan · 3D engineering wireframe · evidence — pinned to graph version <code>${escapeHtml(input.graphSnapshot.versionId)}</code> (drawing <code>${escapeHtml(input.drawing.drawingId)}</code> generated by <code>${escapeHtml(input.drawing.generatedBy)}</code>).</p>`,
142→  ];
143→  if (input.drawing.sourceVersionId !== input.graphSnapshot.versionId) {
144→    lines.push(
145→      `<p class="version-warning" data-version-mismatch="true">Version mismatch: the drawing was generated from <code>${escapeHtml(input.drawing.sourceVersionId)}</code> but the graph snapshot is <code>${escapeHtml(input.graphSnapshot.versionId)}</code> — the panes may show different model versions.</p>`,
146→    );
147→  }
148→  lines.push(`</header>`);
149→  return lines;
150→}
