152→/* ------------------------------------------------------------------ */
153→/* Review banner (VERBATIM server state — never computed here)         */
154→/* ------------------------------------------------------------------ */
155→
156→function reviewBannerLines(review: ReviewState | undefined): string[] {
157→  if (review === undefined) {
158→    return [];
159→  }
160→  return [
161→    `<section class="review-banner" data-review-status="${escapeHtml(review.status)}" aria-label="Review state">`,
162→    `<p><strong>Review — ${escapeHtml(review.status)}</strong> by ${escapeHtml(review.reviewer)} at ${escapeHtml(review.at)}</p>`,
163→    `<p>${escapeHtml(review.note)}</p>`,
164→    `</section>`,
165→  ];
166→}
