168→/* ------------------------------------------------------------------ */
169→/* Panes                                                               */
170→/* ------------------------------------------------------------------ */
171→
172→function pane2dLines(input: WorkspaceInput, svg: string): string[] {
173→  return [
174→    `<section class="pane" id="pane-2d" aria-label="2D floor plan">`,
175→    `<h2>2D — floor plan</h2>`,
176→    svg.trimEnd(),
177→    ...omissionLines(input.drawing.omittedNodes),
178→    `</section>`,
179→  ];
180→}
181→
182→function pane3dLines(
183→  view: { readonly azimuthRad: number; readonly elevationRad: number },
184→  svg: string,
185→  omissions: readonly WireframeOmission[],
186→): string[] {
187→  const azimuthDeg = fmt((view.azimuthRad * 180) / Math.PI);
188→  const elevationDeg = fmt((view.elevationRad * 180) / Math.PI);
189→  return [
190→    `<section class="pane" id="pane-3d" aria-label="3D engineering wireframe">`,
191→    `<h2>3D — engineering wireframe</h2>`,
192→    `<p class="pane-note">Orthographic axonometric wireframe of plane boundary polygons (azimuth ${azimuthDeg}°, elevation ${elevationDeg}°). Full 3D rendering is out of scope — this is an engineering wireframe.</p>`,
193→    svg.trimEnd(),
194→    ...omissionLines(omissions),
195→    `</section>`,
196→  ];
197→}
198→
199→/** Honest omissions: stable node id + reason code, verbatim input order. */
200→function omissionLines(omissions: readonly (OmittedNode | WireframeOmission)[]): string[] {
201→  if (omissions.length === 0) {
202→    return [];
203→  }
204→  const lines = [`<ul class="omissions">`];
205→  for (const omission of omissions) {
206→    lines.push(
207→      `<li data-omitted-node-id="${escapeHtml(omission.nodeId)}" data-reason="${escapeHtml(omission.reason)}">${escapeHtml(omission.nodeId)} — ${escapeHtml(omission.reason)}</li>`,
208→    );
209→  }
210→  lines.push(`</ul>`);
211→  return lines;
212→}
213→
214→function paneEvidenceLines(input: WorkspaceInput): string[] {
215→  const lines = [
216→    `<section class="pane" id="pane-evidence" aria-label="Evidence">`,
217→    `<h2>Evidence</h2>`,
218→    `<ul class="evidence-list">`,
219→  ];
220→  if (input.evidence.length === 0) {
221→    lines.push(`<li class="empty">No evidence records linked in this workspace input.</li>`);
222→  }
223→  for (const entry of input.evidence) {
224→    for (const nodeId of entry.linkedNodeIds) {
225→      const selected = input.selectedNodeId === nodeId;
226→      const invalid = entry.invalidated === true;
227→      const text = [
228→        `${entry.evidenceId} — ${entry.method} — node ${nodeId}`,
229→        invalid ? "INVALIDATED" : "",
230→        entry.note === undefined ? "" : `${entry.note}`,
231→      ]
232→        .filter((part) => part !== "")
233→        .join(" — ");
234→      lines.push(
235→        `<li${invalid ? ` data-invalid="true"` : ""}${selected ? ` data-selected="true"` : ""} data-evidence-id="${escapeHtml(entry.evidenceId)}" data-node-id="${escapeHtml(nodeId)}">${escapeHtml(text)}</li>`,
236→      );
237→    }
238→  }
239→  lines.push(`</ul>`, `</section>`);
240→  return lines;
241→}
242→
243→function paneMeasurementLines(dimensions: readonly Dimension2D[]): string[] {
244→  const lines = [
245→    `<section class="pane" id="pane-measurements" aria-label="Measurements">`,
246→    `<h2>Measurements</h2>`,
247→    `<ul class="measurement-strip">`,
248→  ];
249→  if (dimensions.length === 0) {
250→    lines.push(`<li class="empty">No dimensions on this drawing.</li>`);
251→  }
252→  for (const dimension of dimensions) {
253→    lines.push(
254→      `<li data-dimension-id="${escapeHtml(dimension.dimensionId)}">${escapeHtml(measurementText(dimension))}</li>`,
255→    );
256→  }
257→  lines.push(`</ul>`, `</section>`);
258→  return lines;
259→}
260→
261→/**
262→ * Measurement text: value + unit + σ. An UNKNOWN σ renders as "σ unknown" —
263→ * never as ±0 and never as a fabricated number (null is not 0).
264→ */
265→export function measurementText(dimension: Dimension2D): string {
266→  if (dimension.uncertainty === null) {
267→    return `${fmt(dimension.value)} ${dimension.unit} — σ unknown`;
268→  }
269→  return `${fmt(dimension.value)} ${dimension.unit} ±${fmt(dimension.uncertainty)} ${dimension.unit}`;
270→}
