272→/* ------------------------------------------------------------------ */
273→/* Selection panel                                                     */
274→/* ------------------------------------------------------------------ */
275→
276→function selectionPanelLines(bundle: SelectionBundle): string[] {
277→  const lines = [
278→    `<section class="selection-panel" id="selection-panel" aria-label="Selection" data-selected-node-id="${escapeHtml(bundle.nodeId)}">`,
279→    `<h2>Selection — <code>${escapeHtml(bundle.nodeId)}</code></h2>`,
280→    `<p class="selection-resolution" data-resolved-views="${escapeHtml(bundle.resolvedIn.join(","))}">Resolved in views: ${bundle.resolvedIn.length === 0 ? "none" : escapeHtml(bundle.resolvedIn.join(", "))}</p>`,
281→  ];
282→  if (bundle.node === undefined) {
283→    lines.push(`<p class="selection-missing">Node is not present in the graph snapshot of this version.</p>`);
284→  } else {
285→    lines.push(
286→      `<p class="selection-node" data-node-kind="${escapeHtml(bundle.node.kind)}">Node kind: ${escapeHtml(bundle.node.kind)} — epistemic status: ${escapeHtml(bundle.node.epistemicStatus)}</p>`,
287→    );
288→  }
289→  lines.push(`<h3>Properties</h3>`, `<ul class="selection-properties">`);
290→  if (bundle.properties.length === 0) {
291→    lines.push(`<li class="empty">no properties on this node</li>`);
292→  }
293→  for (const property of bundle.properties) {
294→    lines.push(`<li data-property-key="${escapeHtml(property.key)}">${escapeHtml(propertyText(property))}</li>`);
295→  }
296→  lines.push(`</ul>`, `<h3>Uncertainty (σ)</h3>`, `<ul class="selection-sigmas">`);
297→  if (bundle.sigmas.length === 0) {
298→    lines.push(`<li class="empty">no σ records concern this node</li>`);
299→  }
300→  for (const sigma of bundle.sigmas) {
301→    lines.push(
302→      `<li data-sigma-id="${escapeHtml(sigma.id)}" data-sigma-source="${escapeHtml(sigma.source)}">${escapeHtml(sigmaText(sigma))}</li>`,
303→    );
304→  }
305→  lines.push(`</ul>`, `<h3>2D entries</h3>`, `<ul class="selection-2d">`);
306→  if (bundle.drawingEntries.length === 0) {
307→    lines.push(`<li class="empty">no entries in the 2D view</li>`);
308→  }
309→  for (const entry of bundle.drawingEntries) {
310→    lines.push(
311→      `<li data-element-id="${escapeHtml(entry.elementId)}">${escapeHtml(entry.drawingKind)} · ${escapeHtml(entry.entryKind)} · ${escapeHtml(entry.elementId)}</li>`,
312→    );
313→  }
314→  lines.push(`</ul>`, `<h3>3D entries</h3>`, `<ul class="selection-3d">`);
315→  if (bundle.wireframeEntries.length === 0) {
316→    lines.push(`<li class="empty">no entries in the 3D view</li>`);
317→  }
318→  for (const entry of bundle.wireframeEntries) {
319→    lines.push(
320→      `<li data-element-id="${escapeHtml(entry.nodeId)}">wireframe · ${escapeHtml(entry.geometryId)} · ${entry.screenPoints.length} points · closed</li>`,
321→    );
322→  }
323→  lines.push(`</ul>`, `<h3>Evidence entries</h3>`, `<ul class="selection-evidence">`);
324→  if (bundle.evidenceEntries.length === 0) {
325→    lines.push(`<li class="empty">no evidence linked to this node</li>`);
326→  }
327→  for (const entry of bundle.evidenceEntries) {
328→    lines.push(
329→      `<li data-evidence-id="${escapeHtml(entry.evidenceId)}">${escapeHtml(entry.evidenceId)} · ${escapeHtml(entry.method)}${entry.invalidated === true ? " · INVALIDATED" : ""}</li>`,
330→    );
331→  }
332→  lines.push(`</ul>`, `</section>`);
333→  return lines;
334→}
335→
336→function propertyText(property: WorkspaceProperty): string {
337→  const value =
338→    typeof property.value === "number" && property.unit !== undefined
339→      ? `${fmt(property.value)} ${property.unit}`
340→      : String(property.value);
341→  return `${property.key} = ${value} (${property.epistemicStatus})`;
342→}
343→
344→function sigmaText(sigma: SelectionSigma): string {
345→  return sigma.sigma === null
346→    ? `${sigma.source} ${sigma.id} — σ unknown`
347→    : `${sigma.source} ${sigma.id} — σ ${fmt(sigma.sigma)} m`;
348→}
349→
350→function footerLines(): string[] {
351→  return [
352→    `<footer class="workspace-footer">Server-assembled, read-only projection of the Reality Graph. The browser workspace holds no authority: it never fetches, never computes engineering truth and never alters review state. Generator ${WORKSPACE_GENERATOR_VERSION} (3D view default azimuth ${fmt((DEFAULT_VIEW.azimuthRad * 180) / Math.PI)}°, elevation ${fmt((DEFAULT_VIEW.elevationRad * 180) / Math.PI)}°).</footer>`,
353→  ];
354→}
