  1→/**
  2→ * Workspace boundary rules for the AISE monorepo (AISE-001).
  3→ *
  4→ * The gate enforces a deterministic import-zone matrix so that backend, web,
  5→ * packages and tooling cannot silently grow into each other:
  6→ *
  7→ *   source zone   allowed relative-import target zones
  8→ *   -----------   -------------------------------------
  9→ *   apps          apps, packages
 10→ *   backend       backend, packages
 11→ *   packages      packages
 12→ *   tools         tools
 13→ *   root          (none — root config files must not import workspace source)
 14→ *
 15→ * Bare specifiers (npm packages, node: builtins, bun:test) are unrestricted.
 16→ * Relative imports that escape the repository root are violations.
 17→ *
 18→ * Limitations (intentional): the scanner uses lexical import extraction, not a
 19→ * full parser, and does not follow tsconfig path aliases. It is a tripwire, not
 20→ * a compiler — typecheck and review remain authoritative.
 21→ */
 22→
 23→import { readdirSync, readFileSync } from "node:fs";
 24→import { dirname, join, normalize, relative, sep } from "node:path";
 25→
 26→export type Zone = "apps" | "backend" | "packages" | "tools" | "root";
 27→
 28→export interface SourceFile {
 29→  /** Repo-relative POSIX path. */
 30→  path: string;
 31→  /** Extracted import specifiers (sorted, deduplicated). */
 32→  imports: string[];
 33→}
 34→
 35→export interface BoundaryViolation {
 36→  file: string;
 37→  specifier: string;
 38→  sourceZone: Zone;
 39→  targetZone: Zone | "outside";
 40→  reason: string;
 41→}
 42→
 43→const ZONES: readonly Zone[] = ["apps", "backend", "packages", "tools"];
 44→
 45→const ALLOWED_TARGETS: Record<Zone, readonly Zone[]> = {
 46→  apps: ["apps", "packages"],
 47→  backend: ["backend", "packages"],
 48→  packages: ["packages"],
 49→  tools: ["tools"],
 50→  root: [],
 51→};
 52→
 53→const SCANNED_EXTENSIONS = [".ts", ".tsx", ".js", ".mjs", ".cjs"];
 54→
 55→const SKIPPED_DIRECTORIES = new Set([
 56→  ".git",
 57→  "node_modules",
 58→  "dist",
 59→  "build",
 60→  ".cache",
 61→  ".vercel",
 62→]);
 63→
 64→function toPosix(path: string): string {
 65→  return path.split(sep).join("/");
 66→}
 67→
 68→export function zoneOf(repoRelativePath: string): Zone {
 69→  const first = repoRelativePath.split("/")[0] ?? "";
 70→  return (ZONES as readonly string[]).includes(first) ? (first as Zone) : "root";
 71→}
 72→
 73→/** Lexically extract import specifiers from TypeScript/JavaScript source. */
 74→export function parseImports(code: string): string[] {
 75→  const found = new Set<string>();
 76→  const patterns: RegExp[] = [
 77→    /(?:^|[;{}\s)])import\s+[^;()'"]*?from\s*["']([^"']+)["']/g,
 78→    /(?:^|[;{}\s)])export\s+[^;()'"]*?from\s*["']([^"']+)["']/g,
 79→    /(?:^|[;{}\s)])import\s*["']([^"']+)["']/g,
 80→    /import\(\s*["']([^"']+)["']\s*\)/g,
 81→    /require\(\s*["']([^"']+)["']\s*\)/g,
 82→  ];
 83→  for (const pattern of patterns) {
 84→    pattern.lastIndex = 0;
 85→    let match: RegExpExecArray | null;
 86→    while ((match = pattern.exec(code)) !== null) {
 87→      const specifier = match[1];
 88→      if (specifier !== undefined) {
 89→        found.add(specifier);
 90→      }
 91→    }
 92→  }
 93→  return [...found].sort();
 94→}
 95→
 96→/** Evaluate the zone matrix over parsed source files (pure, deterministic). */
 97→export function evaluateBoundaries(files: readonly SourceFile[]): BoundaryViolation[] {
 98→  const violations: BoundaryViolation[] = [];
 99→  const ordered = [...files].sort((a, b) => a.path.localeCompare(b.path));
100→  for (const file of ordered) {
101→    const sourceZone = zoneOf(file.path);
102→    for (const specifier of file.imports) {
103→      if (!specifier.startsWith(".")) {
104→        continue; // bare specifier: npm package, node: builtin or bun:test
105→      }
106→      const target = toPosix(normalize(join(dirname(file.path), specifier)));
107→      if (target.startsWith("../") || target === "..") {
108→        violations.push({
109→          file: file.path,
110→          specifier,
111→          sourceZone,
112→          targetZone: "outside",
113→          reason: "relative import escapes the repository root",
114→        });
115→        continue;
116→      }
117→      const targetZone = zoneOf(target);
118→      if (!ALLOWED_TARGETS[sourceZone].includes(targetZone)) {
119→        violations.push({
120→          file: file.path,
121→          specifier,
122→          sourceZone,
123→          targetZone,
124→          reason: `${sourceZone} -> ${targetZone} imports are not allowed by the workspace boundary rules`,
125→        });
126→      }
127→    }
128→  }
129→  return violations;
130→}
131→
132→/** Scan the repository tree for TypeScript/JavaScript files and their imports. */
133→export function scanTree(root: string): SourceFile[] {
134→  const files: SourceFile[] = [];
135→  const walk = (dir: string): void => {
136→    const entries = readdirSync(dir, { withFileTypes: true })
137→      .sort((a, b) => a.name.localeCompare(b.name));
138→    for (const entry of entries) {
139→      const full = join(dir, entry.name);
140→      if (entry.isDirectory()) {
141→        if (!SKIPPED_DIRECTORIES.has(entry.name)) {
142→          walk(full);
143→        }
144→        continue;
145→      }
146→      if (!entry.isFile()) {
147→        continue;
148→      }
149→      if (!SCANNED_EXTENSIONS.some((extension) => entry.name.endsWith(extension))) {
150→        continue;
151→      }
152→      const path = toPosix(relative(root, full));
153→      files.push({ path, imports: parseImports(readFileSync(full, "utf8")) });
154→    }
