  1→/**
  2→ * AISE deterministic verify gate (AISE-001).
  3→ *
  4→ * The SINGLE entry point for the program's quality gate. Runs sequentially:
  5→ *
  6→ *   typecheck -> lint -> test -> workspace-boundary checks
  7→ *
  8→ * - stops at the first failing step;
  9→ * - exits non-zero on failure;
 10→ * - always prints a final `VERIFY: PASS` or `VERIFY: FAIL` line.
 11→ *
 12→ * Determinism contract: no network access, no timestamps or random values in
 13→ * assertion outputs, no dependence on execution ordering. The same tree plus
 14→ * the same command must produce the same gate outcome. Log text may contain
 15→ * incidental timings; the outcome and exit code are the gate.
 16→ *
 17→ * Usage:
 18→ *   bun run verify              # all steps
 19→ *   bun run typecheck           # single step
 20→ *   bun run lint                # single step
 21→ *   bun tools/verify.ts test    # any single step directly
 22→ */
 23→
 24→import { existsSync, readdirSync, readFileSync } from "node:fs";
 25→import { join, resolve } from "node:path";
 26→import { evaluateBoundaries, scanTree } from "./lib/boundaries";
 27→
 28→const ROOT = resolve(import.meta.dir, "..");
 29→const TSC_ENTRY = join(ROOT, "node_modules", "typescript", "bin", "tsc");
 30→const ESLINT_ENTRY = join(ROOT, "node_modules", "eslint", "bin", "eslint.js");
 31→
 32→interface Step {
 33→  name: string;
 34→  run: () => boolean;
 35→}
 36→
 37→function runCommand(cmd: string, args: string[], label: string): boolean {
 38→  console.log(`  $ ${label}`);
 39→  const proc = Bun.spawnSync({
 40→    cmd: [cmd, ...args],
 41→    cwd: ROOT,
 42→    stdout: "inherit",
 43→    stderr: "inherit",
 44→  });
 45→  const code = proc.exitCode ?? 1;
 46→  if (code !== 0) {
 47→    console.error(`  ${label} exited with code ${code}`);
 48→  }
 49→  return code === 0;
 50→}
 51→
 52→interface RootPackage {
 53→  workspaces?: string[];
 54→}
 55→
 56→/** Resolve workspace directories ("<parent>/*" globs) that contain a package.json. */
 57→function workspaceDirs(): string[] {
 58→  const rootPackage = JSON.parse(
 59→    readFileSync(join(ROOT, "package.json"), "utf8"),
 60→  ) as RootPackage;
 61→  const globs = Array.isArray(rootPackage.workspaces) ? rootPackage.workspaces : [];
 62→  const dirs = new Set<string>();
 63→  for (const glob of globs) {
 64→    const parent = glob.split("/")[0] ?? "";
 65→    if (!glob.endsWith("/*") || parent === "") {
 66→      continue;
 67→    }
 68→    const parentDir = join(ROOT, parent);
 69→    if (!existsSync(parentDir)) {
 70→      continue;
 71→    }
 72→    for (const entry of readdirSync(parentDir, { withFileTypes: true })) {
 73→      if (entry.isDirectory() && existsSync(join(parentDir, entry.name, "package.json"))) {
 74→        dirs.add(`${parent}/${entry.name}`);
 75→      }
 76→    }
 77→  }
 78→  return [...dirs].sort();
 79→}
 80→
 81→const typecheckStep: Step = {
 82→  name: "typecheck",
 83→  run: () => {
 84→    if (!existsSync(TSC_ENTRY)) {
 85→      console.error("  typescript is not installed — run `bun install --frozen-lockfile` first");
 86→      return false;
 87→    }
 88→    const candidates = [...workspaceDirs(), "tools"].filter((dir) =>
 89→      existsSync(join(ROOT, dir, "tsconfig.json")),
 90→    );
 91→    if (candidates.length === 0) {
 92→      console.error("  no tsconfig.json found in any workspace or in tools/");
 93→      return false;
 94→    }
 95→    for (const dir of candidates) {
 96→      const ok = runCommand(
 97→        process.execPath,
 98→        [TSC_ENTRY, "--noEmit", "-p", join(dir, "tsconfig.json")],
 99→        `tsc --noEmit -p ${dir}/tsconfig.json`,
100→      );
101→      if (!ok) {
102→        return false;
103→      }
104→    }
105→    return true;
106→  },
107→};
108→
109→const lintStep: Step = {
110→  name: "lint",
111→  run: () => {
112→    if (!existsSync(ESLINT_ENTRY)) {
113→      console.error("  eslint is not installed — run `bun install --frozen-lockfile` first");
114→      return false;
115→    }
116→    return runCommand(process.execPath, [ESLINT_ENTRY, "."], "eslint .");
117→  },
118→};
119→
120→const testStep: Step = {
121→  name: "test",
122→  run: () => runCommand(process.execPath, ["test"], "bun test"),
123→};
124→
125→const boundariesStep: Step = {
126→  name: "boundaries",
127→  run: () => {
128→    const files = scanTree(ROOT);
129→    const violations = evaluateBoundaries(files);
130→    console.log(`  scanned ${files.length} source files across apps/, backend/, packages/, tools/`);
131→    if (violations.length === 0) {
132→      console.log("  no cross-zone import violations");
133→      return true;
134→    }
135→    for (const violation of violations) {
136→      console.error(
137→        `  boundary violation: ${violation.file} imports '${violation.specifier}' — ${violation.reason}`,
138→      );
139→    }
140→    return false;
141→  },
142→};
143→
144→const ALL_STEPS: Step[] = [typecheckStep, lintStep, testStep, boundariesStep];
145→
146→const requested = process.argv[2] ?? "all";
147→const steps =
148→  requested === "all" ? ALL_STEPS : ALL_STEPS.filter((step) => step.name === requested);
149→
150→if (steps.length === 0) {
151→  console.error(
152→    `unknown step '${requested}' — expected: all|${ALL_STEPS.map((step) => step.name).join("|")}`,
153→  );
154→  process.exit(2);
155→}
156→
157→console.log("AISE verify — deterministic gate");
158→let passed = true;
159→for (const step of steps) {
160→  console.log(`==> ${step.name}`);
161→  if (!step.run()) {
162→    console.error(`step failed: ${step.name}`);
163→    passed = false;
164→    break;
165→  }
166→}
167→console.log(passed ? "VERIFY: PASS" : "VERIFY: FAIL");
168→process.exit(passed ? 0 : 1);
