    });
    const version = {
      contractVersion: "1.0.0",
      solutionId: "solution-demo-001",
      versionNumber: 1,
      status: "draft" as const,
      operations: [demolition],
      states: [
        {
          contractVersion: "1.0.0",
          stateId: "a".repeat(64),
          solutionId: "solution-demo-001",
          versionNumber: 1,
          stateIndex: 0,
